//! Safe, idiomatic Rust bindings for the portable M3G (`JSR-184`) decoder.
//!
//! Raw FFI is generated by `bindgen` at build time. This crate provides
//! a memory-safe wrapper (`Decoded`) and copies all C-owned data into
//! Rust-owned `Vec`s / `String`s.

/// Raw FFI declarations generated by `bindgen`.
#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]
pub mod ffi {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

use ffi::*;
use std::ffi::{CStr, CString};
use std::fmt;
use std::mem::MaybeUninit;
use std::os::raw::c_char;
use std::path::Path;
use std::ptr;

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorKind {
    Generic,
    Io,
    Format,
    OutOfMemory,
    Backend,
    Range,
    Unknown(i32),
}

#[derive(Debug, Clone)]
pub struct Error {
    pub kind: ErrorKind,
    pub message: String,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m3g {:?}: {}", self.kind, self.message)
    }
}

impl std::error::Error for Error {}

fn last_error() -> String {
    unsafe {
        let p = m3g_last_error();
        if p.is_null() {
            String::new()
        } else {
            CStr::from_ptr(p).to_string_lossy().into_owned()
        }
    }
}

fn kind_from(rc: i32) -> ErrorKind {
    // These constants are generated by bindgen into `ffi`.
    match rc {
        ffi::M3G_ERR => ErrorKind::Generic,
        ffi::M3G_ERR_IO => ErrorKind::Io,
        ffi::M3G_ERR_FORMAT => ErrorKind::Format,
        ffi::M3G_ERR_NOMEM => ErrorKind::OutOfMemory,
        ffi::M3G_ERR_BACKEND => ErrorKind::Backend,
        ffi::M3G_ERR_RANGE => ErrorKind::Range,
        other => ErrorKind::Unknown(other),
    }
}

fn check(rc: i32) -> Result<(), Error> {
    if rc == ffi::M3G_OK {
        Ok(())
    } else {
        Err(Error { kind: kind_from(rc), message: last_error() })
    }
}

// ---------------------------------------------------------------------------
// Backend installation
// ---------------------------------------------------------------------------

pub fn install_default_backends() {
    unsafe {
        m3g_install_portable_math_io();
        #[cfg(feature = "miniz")]
        m3g_install_miniz_deflate_io();
        #[cfg(feature = "stb-image")]
        m3g_install_stb_image_io();
    }
}

pub fn has_deflate_backend() -> bool {
    unsafe { !m3g_get_deflate_io().is_null() }
}

pub fn has_image_backend() -> bool {
    unsafe { !m3g_get_image_io().is_null() }
}

